<?php
namespace qqworld_collector\module\static_cache; class archive extends handler { public function get_args($term, $taxonomy, $page=1) { $t = get_taxonomy( $taxonomy ); if ($taxonomy == 'category') { $args = "index.php?cat={$term->term_id}"; } elseif ($t->query_var) { $args = "index.php?{$t->query_var}={$term->slug}"; } else { $args = "index.php?taxonomy={$taxonomy}&term={$term->slug}"; } if ($page>1) { $args .= "&paged={$page}"; } return $args; } public function make_cache($term_id, $taxonomy = 'category', $page = 'all') { $term_link = get_term_link(intval($term_id), $taxonomy); if ($this->is_excluded($term_link)) return false; $term = get_term_by('id', $term_id, $taxonomy); switch ($this->options->qc_static_cache_mode) { case 'half': $url = $term_link; if ($page == 'all' || $page == 1) { $parser = parse_url($url); $uri = $parser['path']; $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri); $this->set_half_cache($path, $url); if ($page == 'all') { $url = preg_match('/\/$/i', $url) ? $url : $url . '/'; $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; if ($term->count) { $posts_per_page = get_option( 'posts_per_page' ); if ($term->count > $posts_per_page) { $pages = $term->count / $posts_per_page; $pages = is_int($pages) ? $pages : intval($pages) + 1; for ($page=2; $page<=$pages; $page++) { $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . 'page/' . $page); $this->set_half_cache($path, $url . 'page/' . $page); } } } } } else { $parser = parse_url($url); $uri = $parser['path']; $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; $url = preg_match('/\/$/i', $url) ? $url : $url . '/'; $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . 'page/' . $page); $this->set_half_cache($path, $url . 'page/' . $page); } break; case 'pure': $url = str_replace(home_url(), '', $term_link); if ($page == 'all' || $page == 1) { $path = $this->get_path($url, $this->abspath); $args = $this->get_args($term, $taxonomy); $this->set_pure_cache($path, $args); if ($page == 'all') { if ($term->count) { $posts_per_page = get_option( 'posts_per_page' ); if ($term->count > $posts_per_page) { $pages = $term->count / $posts_per_page; $pages = is_int($pages) ? $pages : intval($pages) + 1; if (!preg_match('/\/$/', $url)) $url .= '/'; for ($page=2; $page<=$pages; $page++) { $path = $this->get_path($url . 'page/' . $page, $this->abspath); $args = $this->get_args($term, $taxonomy, $page); $this->set_pure_cache($path, $args); } } } } } else { $path = $this->get_path($url . '/page/' . $page, $this->abspath); $args = $this->get_args($term, $taxonomy, $page); $this->set_pure_cache($path, $args); } break; } return true; } } ?>